// Service Inventory (PoC Mock Data)
// Demonstrates dual-protocol monitoring: HTTP endpoints + SSH server commands.
// Supported types: 'http' | 'ssh'
// Optional 'recipient': overrides the default team routing in BuildAlertDigest.

return [
  {
    json: {
      program_name: "Company Website",
      type: "http",
      target: "https://www.google.com",
      owner_team: "web-ops",
      severity: "warning"
    }
  },
  {
    json: {
      program_name: "Management API",
      type: "http",
      target: "https://httpbin.org/status/500",
      owner_team: "backend",
      severity: "critical"
    }
  },
  {
    json: {
      program_name: "Local Database Service",
      type: "ssh",
      target: "systemctl is-active postgresql",
      owner_team: "dba",
      severity: "critical"
    }
  }
];

// Mock SSH execution for PoC demonstration.
// Change status to "failed" to test the SSH retry & alert path.
return {
  json: {
    status: "success",
    program_name: $('ProgramLoop').first().json.program_name
  }
};

const meta = $('ProgramLoop').first().json;
const result = $input.first().json || {};

const statusCode = typeof result.statusCode === 'number' ? result.statusCode : null;
const hasNetworkError = Boolean(result.error) || (statusCode === null && Boolean(result.message));
const errorMsg = result.error?.message || (hasNetworkError ? result.message : null);

let isUp = false;
if (meta.type === 'http') {
  isUp = !hasNetworkError && statusCode !== null && statusCode >= 200 && statusCode < 300;
} else if (meta.type === 'ssh') {
  isUp = !hasNetworkError && result.status === 'success';
}

return [
  {
    json: {
      ...meta,
      is_up: isUp,
      status_code: statusCode,
      error_detail: isUp
        ? null
        : (errorMsg || (statusCode !== null ? `HTTP ${statusCode}` : 'SSH service check failed')),
      checked_at: new Date().toISOString()
    }
  }
];

// Mock SSH retry execution for PoC demonstration.
return {
  json: {
    status: "success",
    program_name: $('RetryLoop').first().json.program_name
  }
};

const meta = $('RetryLoop').first().json;
const result = $input.first().json || {};

const statusCode = typeof result.statusCode === 'number' ? result.statusCode : null;
const hasNetworkError = Boolean(result.error) || (statusCode === null && Boolean(result.message));
const errorMsg = result.error?.message || (hasNetworkError ? result.message : null);

let isUp = false;
if (meta.type === 'http') {
  isUp = !hasNetworkError && statusCode !== null && statusCode >= 200 && statusCode < 300;
} else if (meta.type === 'ssh') {
  isUp = !hasNetworkError && result.status === 'success';
}

return [
  {
    json: {
      ...meta,
      is_up: isUp,
      status_code: statusCode,
      error_detail: isUp
        ? null
        : (errorMsg || (statusCode !== null ? `HTTP ${statusCode}` : 'SSH retry check failed')),
      retried_at: new Date().toISOString()
    }
  }
];

// Team-based Routing Matrix (Dynamic Alert Routing + Digest Aggregation)
// Groups all confirmed HTTP & SSH outages by team/recipient so a broad outage
// sends 1 digest email per team instead of flooding mailboxes.

const TEAM_ROUTING = {
  backend: "backend-team@example.it, it@example.it",
  dba: "dba-team@example.it, it@example.it",
  "web-ops": "webops@example.it, it@example.it",
  default: "admin@example.it, it@example.it"
};

const items = $input.all().map(i => i.json);
if (items.length === 0) return [];

const checkedAt = typeof $now?.toFormat === "function"
  ? $now.toFormat("dd/MM/yyyy HH:mm")
  : new Date().toISOString().slice(0, 16).replace("T", " ");

const groups = {};
for (const svc of items) {
  const toEmail = svc.recipient || TEAM_ROUTING[svc.owner_team] || TEAM_ROUTING.default;
  const team = svc.owner_team || "general";
  const key = `${team}::${toEmail}`;
  if (!groups[key]) {
    groups[key] = { team, to_email: toEmail, services: [] };
  }
  groups[key].services.push(svc);
}

const escapeHtml = (str) => String(str ?? "")
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;");

return Object.values(groups).map(group => {
  const hasCritical = group.services.some(s => s.severity === "critical");
  const highestSeverity = hasCritical ? "CRITICAL" : "WARNING";
  const count = group.services.length;

  const rowsHtml = group.services.map(s => `
    <tr>
      <td style="padding:8px;border:1px solid #ddd;"><b>${escapeHtml(s.program_name)}</b></td>
      <td style="padding:8px;border:1px solid #ddd;">${escapeHtml((s.type || "").toUpperCase())}</td>
      <td style="padding:8px;border:1px solid #ddd;"><code>${escapeHtml(s.target)}</code></td>
      <td style="padding:8px;border:1px solid #ddd;color:#b91c1c;">${escapeHtml(s.error_detail)}</td>
      <td style="padding:8px;border:1px solid #ddd;">${escapeHtml((s.severity || "warning").toUpperCase())}</td>
    </tr>`).join("");

  const html = `
    <h2>🐍 Anagtia Service Alert (${highestSeverity})</h2>
    <p>Team: <b>${escapeHtml(group.team)}</b> &mdash; Confirmed outages after 60s retry: <b>${count}</b></p>
    <p>Checked at: ${escapeHtml(checkedAt)}</p>
    <table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:14px;">
      <thead>
        <tr style="background:#f3f4f6;text-align:left;">
          <th style="padding:8px;border:1px solid #ddd;">Service</th>
          <th style="padding:8px;border:1px solid #ddd;">Type</th>
          <th style="padding:8px;border:1px solid #ddd;">Target</th>
          <th style="padding:8px;border:1px solid #ddd;">Error Detail</th>
          <th style="padding:8px;border:1px solid #ddd;">Severity</th>
        </tr>
      </thead>
      <tbody>${rowsHtml}</tbody>
    </table>
    <br>
    <p style="color:#6b7280;font-size:12px;">Generated automatically by Anagtia Service Monitor (PoC).</p>
  `;

  const names = group.services.map(s => s.program_name).join(", ");
  const subject = `⚠️ [${highestSeverity}] Anagtia Alert (${group.team}): ${count} service(s) down - ${names}`;

  return {
    json: {
      to_email: group.to_email,
      team: group.team,
      highest_severity: highestSeverity,
      failed_count: count,
      subject,
      html
    }
  };
});
